{
  "meta": {
    "version": 1,
    "description": "Voyage 1: Build TodoMVC app with vanilla JS"
  },
  "watches": [
    {
      "name": "w1-html-css-setup",
      "scenarios": [
        "features/todo-management.feature:App starts with no todos"
      ]
    },
    {
      "name": "w2-todo-management",
      "scenarios": [
        "features/todo-management.feature:User adds a todo",
        "features/todo-management.feature:User trims whitespace from new todo",
        "features/todo-management.feature:User cannot add an empty todo",
        "features/todo-management.feature:User completes a todo",
        "features/todo-management.feature:User uncompletes a todo",
        "features/todo-management.feature:User removes a todo with the destroy button",
        "features/todo-management.feature:Mark all as complete toggles all todos",
        "features/todo-management.feature:Mark all as complete unchecks when a single todo is unchecked",
        "features/todo-management.feature:Mark all as complete checkbox is checked when all todos completed",
        "features/todo-management.feature:Clear completed removes all completed todos",
        "features/todo-management.feature:Clear completed button is hidden when no completed todos",
        "features/todo-management.feature:Clear completed button is visible when completed todos exist",
        "features/todo-management.feature:Counter pluralizes correctly"
      ]
    },
    {
      "name": "w3-todo-editing",
      "scenarios": [
        "features/todo-editing.feature:User enters editing mode by double-clicking the label",
        "features/todo-editing.feature:User saves the edit by pressing Enter",
        "features/todo-editing.feature:User saves the edit by blurring the input",
        "features/todo-editing.feature:User cancels edit by pressing Escape",
        "features/todo-editing.feature:User destroys todo by clearing the edit value and pressing Enter",
        "features/todo-editing.feature:User destroys todo by clearing the edit value and blurring",
        "features/todo-editing.feature:User trims whitespace in edited title"
      ]
    },
    {
      "name": "w4-todo-filtering",
      "scenarios": [
        "features/todo-filtering.feature:Default route shows all todos",
        "features/todo-filtering.feature:Active filter shows only active todos",
        "features/todo-filtering.feature:Completed filter shows only completed todos",
        "features/todo-filtering.feature:Filter persists on reload with route change",
        "features/todo-filtering.feature:Item hidden by filter when its state changes",
        "features/todo-filtering.feature:All filter link is default selected"
      ]
    },
    {
      "name": "w5-todo-persistence",
      "scenarios": [
        "features/todo-persistence.feature:Todos persist across page reload",
        "features/todo-persistence.feature:Completed state persists across page reload",
        "features/todo-persistence.feature:Deleted todo is removed from persistence",
        "features/todo-persistence.feature:Cleared completed todos are cleared from persistence",
        "features/todo-persistence.feature:New todos added after reload persist",
        "features/todo-persistence.feature:Stored data conforms to the expected schema"
      ]
    }
  ]
}

