import json, sys
data = json.load(sys.stdin)
total = 0
for feat in data:
    for sc in feat.get('elements', []):
        if sc.get('type') == 'scenario':
            total += 1
print(f'Total scenarios: {total}')
for feat in data:
    scenarios = [sc['name'] for sc in feat.get('elements', []) if sc.get('type') == 'scenario']
    print(f'  {feat[\"name\"]}: {len(scenarios)} scenarios')
    for s in scenarios:
        print(f'    - {s}')
"
